#include <vector>
#include <iostream>

int main() {
    std::vector<int> vec = {1, -2, 3, -4, 5};

    auto it = vec.begin();
    while (it != vec.end()) {
        if (*it < 0) {
            // erase() returns a valid iterator to the NEXT element.
            it = vec.erase(it); 
        } else {
            // Only increment if we didn't erase anything.
            ++it;
        }
    }

    // Alternatively, in modern C++20:
    // std::erase_if(vec, [](int x){ return x < 0; });

    return 0;
}
